import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

type RunResult = { code: number; stdout: string; stderr: string };
type Run = (cmd: string[]) => Promise<RunResult>;

export interface OpenPrOpts {
  repoPath: string;
  branch: string;
  title: string;
  body: string;
  dryRun?: boolean;
  allowRepo: (ownerRepo: string) => boolean;
  run?: Run;
}

export interface OpenPrResult {
  opened: boolean;
  url?: string;
  command: string[];
  reason?: string;
}

/** Parse owner/repo from an https or ssh GitHub remote URL. */
export function parseOwnerRepo(remote: string): string | null {
  const m = remote
    .trim()
    .match(/^(?:https?:\/\/(?:[^@/]+@)?[^/]+\/|ssh:\/\/(?:[^@/]+@)?[^/]+\/|[^@/\s]+@[^:/\s]+:)([^/\s]+)\/([^/\s]+?)(?:\.git)?\/?$/);
  return m ? `${m[1]}/${m[2]}` : null;
}

function defaultRunner(cwd: string): Run {
  return async (cmd) => {
    const p = Bun.spawn(cmd, { cwd, stdout: "pipe", stderr: "pipe" });
    const [stdout, stderr, code] = await Promise.all([
      new Response(p.stdout).text(),
      new Response(p.stderr).text(),
      p.exited,
    ]);
    return { code, stdout, stderr };
  };
}

export async function openPr(opts: OpenPrOpts): Promise<OpenPrResult> {
  const run = opts.run ?? defaultRunner(opts.repoPath);
  const remoteCmd = ["git", "-C", opts.repoPath, "remote", "get-url", "origin"];
  const bodyFile = join(tmpdir(), "roster-pr-body", "body.md");
  const command = ["gh", "pr", "create", "--head", opts.branch, "--title", opts.title, "--body-file", bodyFile];

  const remote = await run(remoteCmd);
  if (remote.code !== 0) {
    return { opened: false, command: [], reason: remote.stderr.trim() || "could not read origin remote" };
  }
  const ownerRepo = parseOwnerRepo(remote.stdout);
  if (!ownerRepo) return { opened: false, command: [], reason: `unrecognized remote url: ${remote.stdout.trim()}` };
  if (!opts.allowRepo(ownerRepo)) return { opened: false, command: [], reason: "not opted in" };

  if (opts.dryRun) return { opened: false, command, reason: "dry run" };

  const dir = mkdtempSync(join(tmpdir(), "roster-pr-"));
  const file = join(dir, "body.md");
  writeFileSync(file, opts.body);
  const real = command.slice(0, -1).concat(file);
  try {
    const res = await run(real);
    if (res.code !== 0) return { opened: false, command: real, reason: res.stderr.trim() || `exit ${res.code}` };
    const url = res.stdout.match(/https?:\/\/\S+/)?.[0];
    return url ? { opened: true, url, command: real } : { opened: true, command: real };
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}
EOF
