import { expect, test } from "bun:test";
import { openPr, parseOwnerRepo } from "../src/act/open-pr";

const mk = (remote: string, pr = { code: 0, stdout: "https://github.com/o/r/pull/7\n", stderr: "" }) => {
  const calls: string[][] = [];
  const run = async (cmd: string[]) => {
    calls.push(cmd);
    return cmd[0] === "git" ? { code: 0, stdout: remote + "\n", stderr: "" } : pr;
  };
  return { calls, run };
};
const base = { repoPath: "/x", branch: "b", title: "T", body: "B" };

test("parses https and ssh remotes", () => {
  expect(parseOwnerRepo("https://github.com/o/r.git")).toBe("o/r");
  expect(parseOwnerRepo("[REDACTED_EMAIL]:o/r.git")).toBe("o/r");
  expect(parseOwnerRepo("ssh://[REDACTED_EMAIL]/o/r")).toBe("o/r");
});

test("not opted in runs no gh command", async () => {
  const { calls, run } = mk("[REDACTED_EMAIL]:o/r.git");
  const r = await openPr({ ...base, allowRepo: () => false, run });
  expect(r.opened).toBe(false);
  expect(r.reason).toBe("not opted in");
  expect(calls.every((c) => c[0] === "git")).toBe(true);
});

test("dry run returns command without running gh", async () => {
  const { calls, run } = mk("https://github.com/o/r");
  const r = await openPr({ ...base, dryRun: true, allowRepo: (x) => x === "o/r", run });
  expect(r.opened).toBe(false);
  expect(r.command.slice(0, 7)).toEqual(["gh", "pr", "create", "--head", "b", "--title", "T"]);
  expect(r.command).toContain("--body-file");
  expect(calls.some((c) => c[0] === "gh")).toBe(false);
});

test("success parses url", async () => {
  const { run } = mk("https://github.com/o/r");
  const r = await openPr({ ...base, allowRepo: () => true, run });
  expect(r).toMatchObject({ opened: true, url: "https://github.com/o/r/pull/7" });
});

test("non-zero exit gives stderr reason", async () => {
  const { run } = mk("https://github.com/o/r", { code: 1, stdout: "", stderr: "boom\n" });
  const r = await openPr({ ...base, allowRepo: () => true, run });
  expect(r).toMatchObject({ opened: false, reason: "boom" });
});
EOF
bun test tests/open-pr.test.ts 2>&1 | tail -15; bun run typecheck 2>&1 | tail -5

